from datetime import timedelta


def audit_roster(shifts, period_start, period_end, max_consecutive=6):
    worked_days = build_worked_days(shifts)
    return {
        "rest_period": check_rest_periods(shifts),
        "consecutive_days": check_consecutive_days(
            worked_days, period_start, period_end, max_consecutive
        ),
    }


def build_worked_days(shifts):
    days = set()
    for shift in shifts:
        day = shift["start"].date()
        end_day = shift["end"].date()
        while day <= end_day:
            days.add(day)
            day += timedelta(days=1)
    return days


def check_rest_periods(shifts, min_rest_hours=11):
    violations = []
    ordered = sorted(shifts, key=lambda s: s["start"])
    for prev_shift, next_shift in zip(ordered, ordered[1:]):
        gap = next_shift["start"] - prev_shift["end"]
        gap_hours = gap.total_seconds() / 3600
        if gap_hours < min_rest_hours:
            violations.append(
                (prev_shift["employee"], prev_shift["end"], next_shift["start"])
            )
    return violations


def check_consecutive_days(worked_days, period_start, period_end, max_consecutive):
    violations = []
    current = period_start
    while current <= period_end:
        if is_overworked_window(worked_days, current, max_consecutive):
            violations.append(current)
        current += timedelta(days=1)
    return violations


def is_overworked_window(worked_days, window_start, max_consecutive):
    window = [window_start + timedelta(days=i) for i in range(max_consecutive)]
    return all(day in worked_days for day in window)
